files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --muted: #a0a0b0;
  --pixel: 3px solid var(--accent);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image:
    linear-gradient(var(--card) 1px, transparent 1px),
    linear-gradient(90deg, var(--card) 1px, transparent 1px);
  background-size: 24px 24px;
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.quiz {
  background: var(--card);
  border: var(--pixel);
  box-shadow: 6px 6px 0 var(--accent);
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 16px;
  color: var(--accent);
}

.score-label {
  font-size: 1rem;
  color: var(--muted);
  margin-bottom: 8px;
}

#score {
  color: var(--text);
  font-weight: bold;
}

.question {
  font-size: 1.75rem;
  font-weight: bold;
  margin: 24px 0;
  min-height: 2.5rem;
  letter-spacing: 1px;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

button {
  font-family: inherit;
  font-size: 1.125rem;
  font-weight: bold;
  cursor: pointer;
  border: 3px solid var(--accent);
  background: var(--bg);
  color: var(--text);
  padding: 12px 28px;
  transition: transform 0.05s, background 0.1s;
  box-shadow: 3px 3px 0 var(--accent);
}

button:hover:not(:disabled) {
  background: var(--accent);
  color: var(--bg);
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

button:active:not(:disabled) {
  transform: translate(3px, 3px);
  box-shadow: none;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
}

.control {
  font-size: 1rem;
  padding: 10px 20px;
}

@media (max-width: 400px) {
  .quiz {
    padding: 24px 16px;
  }
  .answers {
    flex-direction: column;
    align-items: stretch;
  }
  .question {
    font-size: 1.5rem;
  }
}

const state = {
  score: 0,
  questionIndex: 0,
  answered: false,
};

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' },
];

const scoreEl = document.getElementById('score');
const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

function render() {
  const q = questions[state.questionIndex];
  questionEl.textContent = q ? q.text : 'Finished';
  answerA.textContent = q ? q.a : '';
  answerB.textContent = q ? q.b : '';
  scoreEl.textContent = String(state.score);
  answerA.disabled = state.answered || !q;
  answerB.disabled = state.answered || !q;
  nextBtn.disabled = !state.answered || !q;
}

function selectAnswer(choice) {
  if (state.answered || !questions[state.questionIndex]) return;
  state.answered = true;
  const q = questions[state.questionIndex];
  if (choice === q.correct) {
    state.score += 1;
  }
  render();
}

answerA.addEventListener('click', () => selectAnswer('a'));
answerB.addEventListener('click', () => selectAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (!state.answered) return;
  state.questionIndex += 1;
  state.answered = false;
  render();
});

restartBtn.addEventListener('click', () => {
  state.score = 0;
  state.questionIndex = 0;
  state.answered = false;
  render();
});

render();
